import{_ as a,o as e,c as s,a5 as l}from"./chunks/framework.a5no_H3L.js";const u=JSON.parse('{"title":"多集群拓扑：为什么需要跨集群复制","description":"单集群 Kafka 能覆盖大部分业务规模，扩容可以解决部分容量问题。但真正把架构引向多集群的，是四类无法用单集群回答的问题：","frontmatter":{},"headers":[],"relativePath":"kafka/07-multi-cluster/chapter-01-scenarios.md","filePath":"kafka/07-multi-cluster/chapter-01-scenarios.md"}'),n={name:"kafka/07-multi-cluster/chapter-01-scenarios.md"};function r(i,t,c,d,p,o){return e(),s("div",null,[...t[0]||(t[0]=[l(`<h1 id="多集群拓扑-为什么需要跨集群复制" tabindex="-1" data-src-line="1" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">多集群拓扑：为什么需要跨集群复制 <a class="header-anchor" href="#多集群拓扑-为什么需要跨集群复制" aria-label="Permalink to &quot;多集群拓扑：为什么需要跨集群复制&quot;">​</a></h1><p data-src-line="3" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">单集群 Kafka 能覆盖大部分业务规模，扩容可以解决部分容量问题。但真正把架构引向多集群的，是四类无法用单集群回答的问题：</p><ul data-src-line="5" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><li data-src-line="5" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><strong>一个机房 / 一个 region 挂了，业务能不能继续跑？</strong></li><li data-src-line="6" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><strong>跨地域访问延迟高，能否让每个 region 消费者读本地副本？</strong></li><li data-src-line="7" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><strong>合规要求某类数据不能出境 / 出 region，能否只把脱敏后的数据复制到中心集群？</strong></li><li data-src-line="8" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><strong>多个边缘集群产生数据，如何汇聚到中心做统计分析？</strong></li></ul><p data-src-line="10" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">这四个问题对应四种典型拓扑。选型不当会让复制方案在故障切换时失效，直接影响恢复时间与数据一致性。</p><h2 id="_1-四种典型拓扑" tabindex="-1" data-src-line="12" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">1. 四种典型拓扑 <a class="header-anchor" href="#_1-四种典型拓扑" aria-label="Permalink to &quot;1. 四种典型拓扑&quot;">​</a></h2><h3 id="_1-1-active-standby-灾备" tabindex="-1" data-src-line="14" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">1.1 Active-Standby（灾备） <a class="header-anchor" href="#_1-1-active-standby-灾备" aria-label="Permalink to &quot;1.1 Active-Standby（灾备）&quot;">​</a></h3><p data-src-line="16" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">主集群承担 100% 生产流量，Standby 集群通过复制持续同步。正常情况下 Standby 只是&quot;接盘位&quot;，不对外提供读。当主集群不可用（机房故障、网络分区、误操作）时，业务切到 Standby。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>      producer                 consumer</span></span>
<span class="line"><span>         │                        │</span></span>
<span class="line"><span>         ▼                        ▼</span></span>
<span class="line"><span>   ┌─────────────┐   MM2    ┌─────────────┐</span></span>
<span class="line"><span>   │   Primary   │─────────▶│   Standby   │</span></span>
<span class="line"><span>   │   (active)  │          │  (passive)  │</span></span>
<span class="line"><span>   └─────────────┘          └─────────────┘</span></span></code></pre></div><p data-src-line="28" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><strong>关键决策</strong>：</p><ul data-src-line="30" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><li data-src-line="30" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">Standby 不承接业务写流量——业务应用只向主集群写入，避免脑裂后合并数据无从下手。这一约束需要通过权限、路由和切换流程落实，不能只靠应用约定。</li><li data-src-line="31" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">RPO 目标需预先定义，故障时实际可能丢失的数据取决于主集群中尚未复制到备集群的数据量。复制延迟影响丢失范围，但不能把复制延迟直接当作 RPO 目标。</li><li data-src-line="32" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">RTO（切换时间）= 检测故障 + 切流量 + consumer offset 重定位。offset 翻译是这里的技术难点，详见 <a href="./chapter-03-offset-translation.html">§3 offset translation</a>。</li></ul><p data-src-line="34" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><strong>适用场景</strong>：金融、电商这类核心域。需要独立故障域、希望在主集群故障后恢复服务，且团队具备 SRE 能力、有独立灾备演练流程。是否满足数据丢失与恢复时间目标，仍需结合复制延迟、切换机制和演练结果评估。</p><h3 id="_1-2-active-active-双活" tabindex="-1" data-src-line="36" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">1.2 Active-Active（双活） <a class="header-anchor" href="#_1-2-active-active-双活" aria-label="Permalink to &quot;1.2 Active-Active（双活）&quot;">​</a></h3><p data-src-line="38" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">两个集群同时接收生产流量，互相复制。在剩余集群具备足够容量、必要数据可用且切流机制有效的前提下，可以承接故障区域转移过来的流量。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   ┌─────────────┐    MM2    ┌─────────────┐</span></span>
<span class="line"><span>   │   us-east   │ ────────▶ │   us-west   │</span></span>
<span class="line"><span>   │  (active)   │ ◀──────── │  (active)   │</span></span>
<span class="line"><span>   └─────────────┘    MM2    └─────────────┘</span></span>
<span class="line"><span>        ▲                          ▲</span></span>
<span class="line"><span>        │                          │</span></span>
<span class="line"><span>    east producers            west producers</span></span></code></pre></div><p data-src-line="50" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><strong>关键决策</strong>：</p><ul data-src-line="52" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><li data-src-line="52" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><strong>循环防护</strong>是硬要求。<code>us-east</code> 的 topic <code>orders</code> 复制到 <code>us-west</code> 后叫 <code>us-east.orders</code>；<code>us-west</code> 的 <code>orders</code> 复制到 <code>us-east</code> 后叫 <code>us-west.orders</code>。MM2 默认的 <code>DefaultReplicationPolicy</code> 会为复制过来的 topic 添加源集群别名前缀，并据此识别远端 topic。双向复制时仍需结合源集群配置、topic 选择规则和命名策略验证复制路径，不能把前缀命名本身当作所有配置下的循环防护保证。</li><li data-src-line="53" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><strong>每个 region 的应用只写本地 topic、订阅本地 + 远端前缀 topic</strong>。跨集群复制不会自动合并两份日志，也不会为业务记录建立全局顺序；消费端按业务需求订阅本地 topic 和远端复制 topic。</li><li data-src-line="54" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><strong>数据一致性不是强的</strong>。两侧存在异步复制延迟，延迟大小取决于网络、源端负载和复制任务处理能力，不能预设固定上限。如果业务需要&quot;全球唯一订单号&quot;、&quot;全球计数器&quot;这类强一致语义，Active-Active 不合适。</li></ul><p data-src-line="56" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><strong>适用场景</strong>：跨地域用户就近读写、要求任一 region 挂掉都不影响。典型如全球化的 SaaS。</p><h3 id="_1-3-hub-and-spoke-星型汇聚" tabindex="-1" data-src-line="58" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">1.3 Hub-and-Spoke（星型汇聚） <a class="header-anchor" href="#_1-3-hub-and-spoke-星型汇聚" aria-label="Permalink to &quot;1.3 Hub-and-Spoke（星型汇聚）&quot;">​</a></h3><p data-src-line="60" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">多个边缘集群（spoke）单向复制到一个中心集群（hub），中心做统一分析、归档、二次分发。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   ┌──────────┐  ┌──────────┐  ┌──────────┐</span></span>
<span class="line"><span>   │ edge-BJ  │  │ edge-SH  │  │ edge-GZ  │</span></span>
<span class="line"><span>   └────┬─────┘  └────┬─────┘  └────┬─────┘</span></span>
<span class="line"><span>        │             │             │</span></span>
<span class="line"><span>        └────MM2──────┼───MM2───────┘</span></span>
<span class="line"><span>                      ▼</span></span>
<span class="line"><span>                ┌──────────┐</span></span>
<span class="line"><span>                │ central  │</span></span>
<span class="line"><span>                └──────────┘</span></span></code></pre></div><p data-src-line="74" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><strong>关键决策</strong>：</p><ul data-src-line="76" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><li data-src-line="76" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">只从边缘复制到中心，中心不回写边缘。</li><li data-src-line="77" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">边缘和中心可以设置不同的 topic 保留策略——边缘保留 3 天用于本地实时业务，中心保留 30 天用于分析。但需注意 MM2 的 topic 配置同步：若启用了配置同步，源端保留策略可能同步覆盖目标端，差异化保留需结合 <code>sync.topic.configs.enabled</code> 等配置验证。中心容量预算需按所有边缘的总写入量、保留周期和副本开销计算，不能只按单个边缘集群估算。</li><li data-src-line="78" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">若合规要求限制敏感字段跨地域传输，应在数据离开源集群前落实过滤或脱敏，并验证复制任务不会绕过这条边界；不能把&quot;复制到中心后再脱敏&quot;视为满足出境限制。</li></ul><p data-src-line="80" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><strong>适用场景</strong>：IoT 数据聚合、CDN 上报、多机房日志入湖、跨国公司数据回流到总部。</p><h3 id="_1-4-stretch-cluster-拉伸集群" tabindex="-1" data-src-line="82" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">1.4 Stretch Cluster（拉伸集群） <a class="header-anchor" href="#_1-4-stretch-cluster-拉伸集群" aria-label="Permalink to &quot;1.4 Stretch Cluster（拉伸集群）&quot;">​</a></h3><p data-src-line="84" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">严格来说这不算&quot;多集群&quot;——它是把<strong>单个 Kafka 集群</strong>的 broker 部署到多个可用区（AZ），依赖 Kafka 自身的<a href="./../02-core/chapter-04-replication-and-isr.html">副本机制</a>而不是 MirrorMaker 做跨区容灾。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   ┌─────────── Kafka Cluster ────────────┐</span></span>
<span class="line"><span>   │                                       │</span></span>
<span class="line"><span>   │  ┌───AZ1───┐  ┌───AZ2───┐  ┌───AZ3───┐│</span></span>
<span class="line"><span>   │  │ broker1 │  │ broker2 │  │ broker3 ││</span></span>
<span class="line"><span>   │  │ broker4 │  │ broker5 │  │ broker6 ││</span></span>
<span class="line"><span>   │  └─────────┘  └─────────┘  └─────────┘│</span></span>
<span class="line"><span>   └───────────────────────────────────────┘</span></span></code></pre></div><p data-src-line="96" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><strong>关键决策</strong>：</p><ul data-src-line="98" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><li data-src-line="98" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">通常采用副本因子 ≥ 3、<code>min.insync.replicas = 2</code>，并为 broker 配置正确的 <code>broker.rack</code>，使副本分配考虑 AZ 故障域。部署后应检查每个分区的副本分布，确认单 AZ 故障不会同时移除该分区的全部可用副本；生产者通常还需配合 <code>acks=all</code> 落实写入确认策略（<a href="./../02-core/chapter-04-replication-and-isr.html#isr-definition">ISR</a> 机制详见核心篇）。</li><li data-src-line="99" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">依赖 AZ 之间<strong>稳定且低延迟</strong>的网络。跨 region 部署会显著增加副本同步与写入确认的延迟，并放大网络分区对可用性的影响，因此一般优先考虑独立集群加跨集群复制。</li><li data-src-line="100" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">Kafka 2.4 引入的 KIP-392 支持 consumer 按 <code>client.rack</code> 就近读取副本。这需要对应版本的客户端与 broker 支持、broker 副本选择器配置正确，且目标副本可用；满足这些条件时可减轻跨 AZ 流量，但不能保证每次 fetch 都落在本地 AZ。</li></ul><p data-src-line="102" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><strong>适用场景</strong>：同 region 内多 AZ 容灾，能容忍单 AZ 故障。</p><h2 id="_2-四种拓扑的横向对比" tabindex="-1" data-src-line="104" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">2. 四种拓扑的横向对比 <a class="header-anchor" href="#_2-四种拓扑的横向对比" aria-label="Permalink to &quot;2. 四种拓扑的横向对比&quot;">​</a></h2><table tabindex="0"><thead data-src-line="106" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><tr data-src-line="106" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><th style="text-align:left;">维度</th><th style="text-align:left;">Active-Standby</th><th style="text-align:left;">Active-Active</th><th style="text-align:left;">Hub-and-Spoke</th><th style="text-align:left;">Stretch Cluster</th></tr></thead><tbody data-src-line="108" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><tr data-src-line="108" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><td style="text-align:left;">集群数量</td><td style="text-align:left;">2（1 写 1 备）</td><td style="text-align:left;">2+（都写）</td><td style="text-align:left;">N+1</td><td style="text-align:left;">1（跨 AZ）</td></tr><tr data-src-line="109" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><td style="text-align:left;">数据流向</td><td style="text-align:left;">单向</td><td style="text-align:left;">双向</td><td style="text-align:left;">边缘→中心</td><td style="text-align:left;">集群内部副本</td></tr><tr data-src-line="110" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><td style="text-align:left;">RPO</td><td style="text-align:left;">取决于复制进度</td><td style="text-align:left;">取决于复制进度</td><td style="text-align:left;">取决于复制进度</td><td style="text-align:left;">取决于副本与确认策略</td></tr><tr data-src-line="111" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><td style="text-align:left;">RTO</td><td style="text-align:left;">取决于检测、切流与位点恢复</td><td style="text-align:left;">取决于检测、切流与消费恢复</td><td style="text-align:left;">不适用</td><td style="text-align:left;">取决于故障检测、Leader 选举及客户端恢复</td></tr><tr data-src-line="112" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><td style="text-align:left;">循环风险</td><td style="text-align:left;">单向复制时风险较低</td><td style="text-align:left;">需前缀防护并验证配置</td><td style="text-align:left;">单向复制时风险较低</td><td style="text-align:left;">不适用</td></tr><tr data-src-line="113" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><td style="text-align:left;">一致性</td><td style="text-align:left;">主-备异步复制</td><td style="text-align:left;">两侧异步复制</td><td style="text-align:left;">中心可能落后边缘</td><td style="text-align:left;">分区内通过副本复制、ISR 与 Leader 选举维护一致性</td></tr><tr data-src-line="114" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><td style="text-align:left;">依赖 MirrorMaker</td><td style="text-align:left;">是</td><td style="text-align:left;">是</td><td style="text-align:left;">是</td><td style="text-align:left;">否</td></tr><tr data-src-line="115" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><td style="text-align:left;">典型跨机房距离</td><td style="text-align:left;">取决于网络条件</td><td style="text-align:left;">取决于网络条件</td><td style="text-align:left;">取决于网络条件</td><td style="text-align:left;">同 region 内</td></tr><tr data-src-line="116" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><td style="text-align:left;">复杂度</td><td style="text-align:left;">中</td><td style="text-align:left;">高</td><td style="text-align:left;">中</td><td style="text-align:left;">低（另需跨 AZ 网络与副本布局）</td></tr></tbody></table><p data-src-line="118" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">表中描述的是常见部署方式，并非各拓扑固化的 SLA；RPO、RTO 与可用性目标需结合具体配置与故障演练确定。</p><h2 id="_3-选型决策树" tabindex="-1" data-src-line="120" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">3. 选型决策树 <a class="header-anchor" href="#_3-选型决策树" aria-label="Permalink to &quot;3. 选型决策树&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>              需要跨 region 容灾？</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>        ┌───────────┴───────────┐</span></span>
<span class="line"><span>        否                       是</span></span>
<span class="line"><span>        │                       │</span></span>
<span class="line"><span>   同 region 内多 AZ？         用户是否分散多 region？</span></span>
<span class="line"><span>        │                       │</span></span>
<span class="line"><span>   Stretch Cluster    ┌─────────┴─────────┐</span></span>
<span class="line"><span>                     是                    否</span></span>
<span class="line"><span>                     │                    │</span></span>
<span class="line"><span>             读写就近？            核心域 or 分析？</span></span>
<span class="line"><span>                     │                    │</span></span>
<span class="line"><span>              Active-Active     ┌─────────┴────────┐</span></span>
<span class="line"><span>                              核心域              分析</span></span>
<span class="line"><span>                                │                  │</span></span>
<span class="line"><span>                       Active-Standby      Hub-and-Spoke</span></span></code></pre></div><p data-src-line="141" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">上述决策树是快速选型的参考路径。多集群架构常需要组合部署，例如区域内采用 Stretch Cluster 做多 AZ 容灾，同时通过 MM2 向另一个 region 的备集群复制；不必把四种拓扑理解为严格四选一。</p><h2 id="_4-与-cluster-linking-confluent-replicator-的关系" tabindex="-1" data-src-line="143" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">4. 与 Cluster Linking / Confluent Replicator 的关系 <a class="header-anchor" href="#_4-与-cluster-linking-confluent-replicator-的关系" aria-label="Permalink to &quot;4. 与 Cluster Linking / Confluent Replicator 的关系&quot;">​</a></h2><p data-src-line="145" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">MirrorMaker 2 不是唯一选择：</p><table tabindex="0"><thead data-src-line="147" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><tr data-src-line="147" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><th style="text-align:left;">工具</th><th style="text-align:left;">定位</th><th style="text-align:left;">许可</th></tr></thead><tbody data-src-line="149" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><tr data-src-line="149" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><td style="text-align:left;"><strong>MirrorMaker 2</strong></td><td style="text-align:left;">Apache Kafka 官方，基于 Kafka Connect</td><td style="text-align:left;">Apache 2.0</td></tr><tr data-src-line="150" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><td style="text-align:left;"><strong>Confluent Replicator</strong></td><td style="text-align:left;">Confluent 商业版跨集群复制</td><td style="text-align:left;">商业许可</td></tr><tr data-src-line="151" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><td style="text-align:left;"><strong>Confluent Cluster Linking</strong></td><td style="text-align:left;">Broker 原生跨集群订阅，无 Connect 中转</td><td style="text-align:left;">商业许可</td></tr><tr data-src-line="152" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><td style="text-align:left;"><strong>Uber uReplicator</strong></td><td style="text-align:left;">Uber 自研，早期为解决 MM1 局限</td><td style="text-align:left;">开源</td></tr><tr data-src-line="153" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><td style="text-align:left;"><strong>LinkedIn Brooklin</strong></td><td style="text-align:left;">LinkedIn 自研，多源多目标数据管道</td><td style="text-align:left;">开源</td></tr></tbody></table><p data-src-line="155" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">本文后续以 Apache Kafka 官方的 MirrorMaker 2 为主线，介绍拓扑设计、复制配置、消费者位点转换和灾备演练。其他实现的维护状态、兼容性与运维成本需结合具体项目单独评估。</p><h2 id="_5-本目录导航" tabindex="-1" data-src-line="157" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md">5. 本目录导航 <a class="header-anchor" href="#_5-本目录导航" aria-label="Permalink to &quot;5. 本目录导航&quot;">​</a></h2><table tabindex="0"><thead data-src-line="159" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><tr data-src-line="159" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><th style="text-align:left;">章节</th><th style="text-align:left;">主题</th></tr></thead><tbody data-src-line="161" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><tr data-src-line="161" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><td style="text-align:left;"><a href="./chapter-02-mirrormaker2.html">§2 MirrorMaker 2 架构与配置</a></td><td style="text-align:left;">三个 Connector、内部 topic、<code>DefaultReplicationPolicy</code></td></tr><tr data-src-line="162" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><td style="text-align:left;"><a href="./chapter-03-offset-translation.html">§3 Offset 翻译与消费者切换</a></td><td style="text-align:left;"><code>offset-syncs</code> / <code>checkpoints</code> 机制、<code>RemoteClusterUtils</code></td></tr><tr data-src-line="163" data-src-file="kafka/07-multi-cluster/chapter-01-scenarios.md"><td style="text-align:left;"><a href="./chapter-04-dr-drill.html">§4 灾备演练与切换流程</a></td><td style="text-align:left;">Runbook、切流量顺序、回切策略</td></tr></tbody></table>`,41)])])}const k=a(n,[["render",r]]);export{u as __pageData,k as default};
